    s = (s or '').strip().lower()
    if s.startswith('v'):
        return 'void'
    if s.startswith('c') or s.startswith('a'):
        return 'correction'
    return 'new'


def norm_status(s):
    s = re.sub(r'[\s\-]+', '_', (s or '').strip().lower())
    return HSTAT.get(s, s)


def counted(st):
    return st in ('delivered', 'delivered_late')


def parse_num(s, dec_comma):
    s = s.strip()
    if dec_comma:
        s = s.replace('.', '').replace(',', '.')
    else:
        s = s.replace(',', '')
    return Decimal(s)


def weight_kg(raw, unit, dec_comma):
    raw = (raw or '').strip()
    m = re.match(r'^([-+0-9.,]+)\s*(kg|lb|oz|g)\b', raw, re.I)
    if m:
        raw, unit = m.group(1), m.group(2).lower()
    if raw == '':
        return None
    return parse_num(raw, dec_comma) * FACT[unit]


def parse_date(s, form):
    s = (s or '').strip()
    if not s:
        return None
    if re.match(r'^\d{4}-\d\d-\d\dT', s):
        d = datetime.fromisoformat(s.replace('Z', '+00:00').replace('z', '+00:00'))
        if d.tzinfo is not None:
            d = d.astimezone(timezone.utc)
        return d.date()
    m = re.match(r'^(\d{1,2}) ([A-Za-z]{3})[a-z]* (\d{4})$', s)
    if m:
        return date(int(m.group(3)), MONTHS[m.group(2).lower()], int(m.group(1)))
    f = (form or '').strip()
    if f.lower() == 'serial':
        return date(1899, 12, 30) + timedelta(days=int(float(s)))
    n = [int(x) for x in re.findall(r'\d+', s)]
    if f in ('iso', 'YMD', 'YYYY-MM-DD'):
        return date(n[0], n[1], n[2])
    if f in ('DMY', 'DD-MM-YYYY', 'DD/MM/YYYY', 'DD.MM.YYYY'):
        return date(n[2], n[1], n[0])
    if f in ('MM/DD/YYYY', 'MDY'):
        return date(n[2], n[0], n[1])
    if f == 'YYYYMMDD':
        return date(int(s[:4]), int(s[4:6]), int(s[6:8]))
    if len(n) == 3:
        if n[0] > 999:
            return date(n[0], n[1], n[2])
        return date(n[2], n[1], n[0])
    raise ValueError(s)


def mkrec(typ, num, d, kg, st):
    return {'type': typ, 'num': num, 'date': d, 'kg': kg, 'status': st}


def read_delimited(depot, text):
    delim, cols, base_unit, base_form, dec_comma = CFG[depot]
    seq = None
    dirs = {}
    hdr = None
    recs = []
    if delim == ',':
        rows = csv.reader(io.StringIO(text, newline=''), delimiter=',')
    else:
        rows = (l.rstrip('\r').split(delim) for l in text.split('\n'))
    for r in rows:
        if not r or (len(r) == 1 and r[0].strip() == ''):
            continue
        if r[0].startswith('#'):
            line = delim.join(r)
            m = re.match(r'^#\s*([^:=]+?)\s*[:=]\s*(.*)$', line)
            if m:
                k = m.group(1).strip().lower()
                v = m.group(2).strip()
                dirs[k] = v
                if k == 'seq':
                    seq = int(v)
            else:
                m = re.search(r'seq\s*=\s*(\d+)', line)
                if m:
                    seq = int(m.group(1))
            continue
        rs = [x.strip() for x in r]
        if all(x in cols for x in rs) and len(set(rs)) == len(rs):
            hdr = rs
            continue
        if hdr is None:
            continue
        r = list(r)
        row_unit = None
        wcol = next((i for i, h in enumerate(hdr) if h in FIELDS['weight']), None)
        if len(r) == len(hdr) + 1 and wcol is not None and r[wcol + 1].strip().lower() in FACT:
            row_unit = r[wcol + 1].strip().lower()
            del r[wcol + 1]
        row = dict(zip(hdr, r + [''] * (len(hdr) - len(r))))

        def get(name):
            for c in FIELDS[name]:
                if c in row:
                    return row[c]
            return ''
        num = norm_id(get('id'))
        if num is None:
            continue
        typ = norm_type(get('type'))
        if typ == 'void':
            recs.append(mkrec('void', num, None, None, None))
            continue
        wcolname = next((c for c in FIELDS['weight'] if c in row), None)
        unit = None
        for cand in ('kg', 'g', 'lb', 'oz'):
            if wcolname and wcolname.endswith('_' + cand):
                unit = cand
        if unit is None:
            unit = row_unit
        if unit is None:
            for k in ('unit', 'weight unit'):
                if k in dirs:
                    m = re.match(r'\s*(kg|lb|oz|g)\b', dirs[k], re.I)
                    if m:
                        unit = m.group(1).lower()
                    break
        if unit is None:
            unit = base_unit
        form = dirs.get('dates') or dirs.get('date format') or dirs.get('date') or base_form
        form = form.split()[0] if form else base_form
        kg = weight_kg(get('weight'), unit, dec_comma)
        recs.append(mkrec(typ, num, parse_date(get('date'), form), kg, norm_status(get('status'))))
    return seq, recs


def read_north(text):
    seq = None
    recs = []
    for line in text.split('\n'):
        line = line.strip()
        if not line:
            continue
        try:
            v = json.loads(line)
        except ValueError:
            continue
        objs = v if isinstance(v, list) else [v]
        for o in objs:
            if not isinstance(o, dict):
                continue
            if 'meta' in o and isinstance(o['meta'], dict):
                if 'seq' in o['meta']:
                    seq = int(o['meta']['seq'])
                continue
            num = norm_id(str(o.get('id', '')))
            if num is None:
                continue
            typ = norm_type(o.get('kind'))
            if typ == 'void':
                recs.append(mkrec('void', num, None, None, None))
                continue
            kg = None
            for k, val in o.items():
                m = re.match(r'^weight_(kg|lb|oz|g)$', k)
                if m:
                    kg = weight_kg(str(val), m.group(1), False)
            if kg is None and 'weight' in o:
                kg = weight_kg(str(o['weight']), (o.get('unit') or o.get('weight_unit') or 'kg').lower(), False)
            recs.append(mkrec(typ, num, parse_date(o.get('shipped_at') or o.get('shipped'), 'iso'), kg,
                              norm_status(o.get('status'))))
    return seq, recs


def read_central(text):
    text = re.sub(r'^\s*<\?xml[^>]*\?>', '', text)
    root = ET.fromstring(text)
    seq = int(root.get('seq')) if root.get('seq') else None
    runit = (root.get('weight-unit') or 'kg').lower()
    recs = []
    for sh in root.iter('shipment'):
        num = norm_id(sh.get('id'))
        if num is None:
            continue
        typ = norm_type(sh.get('type'))
        if typ == 'void':
            recs.append(mkrec('void', num, None, None, None))
            continue

        def val(name):
            e = sh.find(name)
            if e is not None and e.text is not None:
                return e.text.strip()
            return sh.get(name)
        w = sh.find('weight')
        if w is not None:
            unit = (w.get('unit') or runit).lower()
            wt = w.text or ''
        else:
            unit = (sh.get('unit') or runit).lower()
            wt = sh.get('weight') or ''
        kg = weight_kg(wt, unit, False)
        recs.append(mkrec(typ, num, parse_date(val('shipped'), 'iso'), kg, norm_status(val('status'))))
    return seq, recs


LAYOUTS = {
    'FW1': dict(len=42, id=(0, 9), type=(9, 10), date=(10, 17), w=(17, 25), st=(25, 26), dt='doy', unit='g', div=1),
    'FW2': dict(len=43, type=(0, 1), id=(1, 10), date=(10, 18), w=(18, 26), st=(26, 27), dt='ymd', unit='kg', div=100),
    'FW3': dict(len=41, id=(0, 9), date=(9, 16), type=(16, 17), w=(17, 24), st=(24, 25), dt='doy', unit='lb', div=10),
}


def read_south(text):
    seq = None
    cur = None
    recs = []
    for line in text.split('\n'):
        line = line.rstrip('\r')
        if '\f' in line or line.startswith('SOUTH DEPOT'):
            continue
        if line.strip() == '':
            continue
        if line.startswith('#'):
            m = re.match(r'^#LAYOUT\s+(\w+)', line)
            if m:
                cur = m.group(1)
            m = re.match(r'^#SEQ\s+(\d+)', line)
            if m:
                seq = int(m.group(1))
            continue
        lay = None
        for k, L in LAYOUTS.items():
            if len(line) == L['len']:
                lay = k
        if lay is None:
            lay = cur
            if lay not in LAYOUTS or len(line) > LAYOUTS[lay]['len']:
                continue
            line = line.ljust(LAYOUTS[lay]['len'])
        L = LAYOUTS[lay]

        def f(k):
            return line[L[k][0]:L[k][1]]
        num = norm_id(f('id'))
        if num is None:
            continue
        typ = norm_type(f('type'))
        if typ == 'void':
            recs.append(mkrec('void', num, None, None, None))
            continue
        ds = f('date')
        if L['dt'] == 'doy':
            d = date(int(ds[:4]), 1, 1) + timedelta(days=int(ds[4:]) - 1)
        else:
            d = date(int(ds[:4]), int(ds[4:6]), int(ds[6:8]))
        kg = Decimal(int(f('w'))) / L['div'] * FACT[L['unit']]
        recs.append(mkrec(typ, num, d, kg, FWSTAT.get(f('st').strip().upper(), f('st').strip().lower())))
    return seq, recs


def main():
    data_dir, out_file = sys.argv[1], sys.argv[2]
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        p = os.path.join(data_dir, name)
        if not os.path.isfile(p):
            continue
        depot = name.split('-')[0]
        exports.setdefault(depot, [])
        with open(p, 'rb') as fh:
            text = decode(fh.read())
        if depot == 'central':
            seq, recs = read_central(text)
        elif depot == 'north':
            seq, recs = read_north(text)
        elif depot == 'south':
            seq, recs = read_south(text)
        elif depot in CFG:
            seq, recs = read_delimited(depot, text)
        else:
            continue
        exports[depot].append((seq if seq is not None else -1, name, recs))
    corrections = resends = 0
    current = {}
    for depot, lst in exports.items():
        cur = {}
        lst.sort(key=lambda x: (x[0], x[1]))
        for seq, name, recs in lst:
            for r in recs:
                n = r['num']
                if r['type'] == 'new':
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = r
                elif r['type'] == 'correction':
                    cur[n] = r
                    corrections += 1
                else:
                    cur.pop(n, None)
                    corrections += 1
        current[depot] = cur
    rank = lambda d: ORDER.index(d) if d in ORDER else len(ORDER)
    owners = {}
    for depot in sorted(current, key=lambda d: (rank(d), d)):
        for n, r in current[depot].items():
            owners.setdefault(n, []).append((depot, r))
    handovers = sum(1 for v in owners.values() if len(v) > 1)
    deps = {d: [0, Decimal(0)] for d in exports}
    months = {}
    for n, v in owners.items():
        depot, r = v[0]
        if not counted(r['status']) or r['kg'] is None or r['date'] is None:
            continue
        deps[depot][0] += 1
        deps[depot][1] += r['kg']
        mk = '%04d-%02d' % (r['date'].year, r['date'].month)
        m = months.setdefault(mk, [0, Decimal(0)])
        m[0] += 1
        m[1] += r['kg']
    rnd = lambda x: float(x.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
    out = {
        'depots': {d: {'shipments': deps[d][0], 'total_kg': rnd(deps[d][1])} for d in sorted(deps)},
        'months': {k: {'shipments': months[k][0], 'total_kg': rnd(months[k][1])} for k in sorted(months)},
        'corrections_applied': corrections,
        'resends_dropped': resends,
        'handovers': handovers,
    }
    with open(out_file, 'w') as fh:
        json.dump(out, fh, indent=2)


